data_fx_pair_promotion_abort_v1<-function(code){if(!is.character(code)||length(code)!=1L||!grepl("^(data|desktop)_fx_pair_promotion_[a-z_]+$",code))code<-"data_fx_pair_promotion_boundary_failed";stop(structure(list(message=code,call=NULL,code=code),class=c("spot_data_fx_pair_promotion_error_v1","error","condition")))}
new_data_fx_pair_promotion_service_v1<-function(project_root,context){
 root<-normalizePath(project_root,winslash="/",mustWork=TRUE);python<-Sys.which("python3");cli<-file.path(root,"scripts","desktop_fx_pair_promotion.py");space<-runtime_data_space_path(context);ctx<-list(tenant_id=context$tenant_id,user_id=context$user_id,data_space_id=context$data_space_id,actor_id="market_worker",role="market_worker");cache<-new.env(hash=TRUE,parent=emptyenv())
 run<-function(cmd,p){o<-suppressWarnings(system2(python,c("-B","-E","-s",shQuote(cli),cmd),stdout=TRUE,stderr=TRUE,input=as.character(jsonlite::toJSON(p,auto_unbox=TRUE,null="null",digits=NA))));s<-attr(o,"status");if(is.null(s))s<-0L;x<-tryCatch(jsonlite::fromJSON(tail(o,1),simplifyVector=FALSE),error=function(e)NULL);if(is.null(x)||s!=0L||!identical(x$status,"completed"))data_fx_pair_promotion_abort_v1(if(is.null(x$code))"data_fx_pair_promotion_boundary_failed"else x$code);x}
 preview<-function(probe,now){x<-run("preview",list(context=ctx,data_space_path=space,probe_result=probe,created_at_utc=now));ref<-paste0("fxmp_",substr(x$trusted_preview$preview_fingerprint,1,32));x$public_preview$preview_ref<-ref;assign(ref,list(trusted=x$trusted_preview,public=x$public_preview),cache);x$public_preview}
 publish<-function(public,confirmed,now){if(!isTRUE(confirmed)||is.null(public$preview_ref)||!exists(public$preview_ref,cache,inherits=FALSE))data_fx_pair_promotion_abort_v1("data_fx_pair_promotion_confirmation_required");x<-get(public$preview_ref,cache);if(!identical(x$public,public))data_fx_pair_promotion_abort_v1("data_fx_pair_promotion_preview_invalid");p<-public;p$preview_ref<-NULL;run("apply",list(context=ctx,data_space_path=space,trusted_preview=x$trusted,public_preview=p,confirmed=TRUE,completed_at_utc=now))$result}
 structure(list(preview=preview,publish=publish,provider_access=FALSE,network_access=FALSE,provider_refetch=FALSE,canonical_write=FALSE),class=c("spot_data_fx_pair_promotion_service_v1","list"))
}
